#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

struct Packet {
    int sequence_num;
    std::string payload;
};

int main() {
    // Simulated out-of-order received packets across the network
    std::vector<Packet> buffer = {
        {3, "Web"},
        {1, "The"},
        {4, "Protocol"},
        {2, "TCP/IP"}
    };

    // Sort packets by their sequence number (TCP in-order reassembly)
    std::sort(buffer.begin(), buffer.end(), [](const Packet& a, const Packet& b) {
        return a.sequence_num < b.sequence_num;
    });

    // Reconstruct the message
    std::string assembled_message;
    for (std::size_t i = 0; i < buffer.size(); ++i) {
        assembled_message += buffer[i].payload;
        if (i + 1 < buffer.size()) {
            assembled_message += " ";
        }
    }

    std::cout << "Reassembled: " << assembled_message << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <numeric>
#include <iomanip>

// Represents an IoT sensor data point reporting via a Web Service
struct IoTDataPoint {
    std::string device_id;
    std::string service_source; // e.g., WeatherBug, SmartMeter
    double reading;
};

int main() {
    // Simulating a Mashup aggregating data feeds from two web services
    std::vector<IoTDataPoint> feed = {
        {"sensor_alpha", "WeatherBug", 28.5},
        {"sensor_beta",  "WeatherBug", 29.5},
        {"sensor_gamma", "SmartMeter", 12.0}
    };

    double weather_sum = 0.0;
    int weather_count = 0;

    for (const auto& item : feed) {
        std::cout << "Feed: [" << item.service_source << "] "
                  << item.device_id << " = " << std::fixed << std::setprecision(1)
                  << item.reading << "\n";
        if (item.service_source == "WeatherBug") {
            weather_sum += item.reading;
            weather_count++;
        }
    }

    if (weather_count > 0) {
        std::cout << "Average Weather: " << (weather_sum / weather_count) << " C\n";
    }

    return 0;
}
